alter table public.family_rosters add column playing_adults integer[] not null default '{}'::integer[], add column playing_kids integer[] not null default '{}'::integer[];
alter table public.family_rosters add constraint roster_adult_selection check(cardinality(playing_adults)<=cardinality(adults) and array_position(playing_adults,null) is null and (cardinality(playing_adults)=0 or (0<=all(playing_adults) and cardinality(adults)>all(playing_adults)))), add constraint roster_kid_selection check(cardinality(playing_kids)<=cardinality(kids) and array_position(playing_kids,null) is null and (cardinality(playing_kids)=0 or (0<=all(playing_kids) and cardinality(kids)>all(playing_kids))));
